import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [first, second] = input;
const [, x] = first.split(" ").map(Number);
const coins = second.split(" ").map(Number);
const MOD = 1_000_000_007;

// ways[s] = s 円の作り方の数。硬貨の種類を外側のループにする
const ways = new Array(x + 1).fill(0);
ways[0] = 1;
for (const c of coins) {
  for (let s = c; s <= x; s++) {
    ways[s] = (ways[s] + ways[s - c]) % MOD;
  }
}
console.log(ways[x]);
